#!/bin/bash
# copy_undistort.sh <device> <fx> <fy> <cx> <cy> <dist0> [dist1 ...]
#
# Writes a camera calibration result to <camera name>.rc next to the robot'svmultimedia_parameters.rc 
# The generated file holds bool undistort = true; and a struct undistort_params { ... }


set -u

if [ "$#" -lt 6 ]; then
  echo "Usage: $0 <device> <fx> <fy> <cx> <cy> <dist0> [dist1 ...]" >&2
  exit 1
fi

DEVICE=$1
FX=$2
FY=$3
CX=$4
CY=$5
shift 5
DIST="$*"

RC_DIR=~/TRHex/config/robots/$(hostname)

if [ ! -d "$RC_DIR" ]; then
  echo "copy_undistort.sh: no such directory: $RC_DIR" >&2
  exit 1
fi

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
MAP_CAMS_SCRIPT="$SCRIPT_DIR/map_cams.sh"

# $DEVICE may be a raw /dev/videoX node or a map_cams.sh mapped name, passed
# either bare ("frontcam") or as a synthetic path ("/dev/frontcam") -- the
# mapping (not the filesystem) is authoritative here, so this works even if
# no /dev/frontcam node actually exists on disk.
if [ -n "$("$MAP_CAMS_SCRIPT" -n "$DEVICE" 2>/dev/null)" ]; then
  CAMERA_NAME="${DEVICE#/dev/}"
else
  CAMERA_NAME=$("$MAP_CAMS_SCRIPT" -p "$DEVICE" 2>/dev/null)
  [ -n "$CAMERA_NAME" ] || CAMERA_NAME=$(basename "$DEVICE")
fi

RC_FILE="$RC_DIR/$CAMERA_NAME.rc"
TMP_FILE="${RC_FILE}.tmp.$$"

cat > "$TMP_FILE" <<EOF || { rm -f "$TMP_FILE"; exit 1; }
# Generated by copy_undistort.sh on $(date '+%Y-%m-%d %H:%M:%S') -- do not edit by hand.
bool undistort = true;

struct undistort_params {
  float fx = $FX;
  float fy = $FY;
  float cx = $CX;
  float cy = $CY;
  float distortion_coeffs = $DIST;
}
EOF

mv "$TMP_FILE" "$RC_FILE"

echo "Wrote undistort params for $DEVICE to $RC_FILE"
exit 0
